"""Note113 : test sauvegarde sans maintien involontaire du mute, diagnostics conserves."""
import argparse,json,pathlib,re,shutil,subprocess,tempfile
ROOT=pathlib.Path(__file__).resolve().parents[1];STAMP='2026-10-17-quick-save-test-3'
JS='''// Note113 : fermer la vue mute via le natif, pas seulement ses drapeaux.
(()=>{const a=window.MCFlasherApp,b=window.MCBuilder,d=window.MCQuickSaveLatch,n=x=>typeof x==='string'?parseInt(x,16):x,h=x=>(x>>>0).toString(16).padStart(8,'0'),hash=x=>b.hex(b.sha256(x));
window.MCQuickSaveLatchReady=window.MCQuickSaveReady.then(()=>{const previous=window.MCMidiBankCompose;window.MCMidiBankCompose=(...args)=>{const prior=previous(...args),slot=0x40100c44;const matches=prior.tweaks.flatMap(t=>(t.writes||[]).filter(w=>0x40000400+w.off<=slot+1&&slot+4<=0x40000400+w.off+w.new.length/2).map(w=>({t,w})));if(!matches.length)return prior;if(matches.length!==1)throw Error('Quick save exit: ambiguous mute vtable');const r={...prior,tweaks:JSON.parse(JSON.stringify(prior.tweaks)),refMods:{...prior.refMods}},owner=r.tweaks.find(t=>t.id==='control-all-beat-repeat');if(!owner)throw Error('Quick save exit test: select Control All Beat Repeat');const origin=(n(owner.append.dest)+owner.append.size+15)&~15,t=r.tweaks.find(t=>t.id===matches[0].t.id),w=t.writes.find(w=>w.off===matches[0].w.off),start=0x40000400+w.off;if(start===slot+1){if(w.new!=='148744'||w.old!=='0234b6')throw Error('Quick save exit: mute pointer guard');w.off--;w.old='40'+w.old;w.new=h(origin);}else{const i=2*(slot-start);if(w.new.slice(i,i+8)!=='40148744')throw Error('Quick save exit: mute pointer guard');w.new=w.new.slice(0,i)+h(origin)+w.new.slice(i+8);}owner.append.parts.push({dest:'0x'+h(origin),hex:d.hex});owner.append.size=origin+d.hex.length/2-n(owner.append.dest);owner.symbols.qs_exit='0x'+h(origin);const loader=owner.writes.find(w=>0x40000400+w.off===window.MCBeatRepeat.boot.at);if(!loader)throw Error('Quick save exit: loader missing');const boot=b.fromHex(loader.new);new DataView(boot.buffer).setUint32(window.MCBeatRepeat.boot.symbols.br_boot_size,owner.append.size,false);loader.new=b.hex(boot);const c=b.parseContainer(b.unwrap(args[1]).stream),section=c.sections.find(s=>s.id===3),stock=b.aplibDepack(c.blob.subarray(section.off,section.off+section.size)).data;for(const changed of new Set([t,owner]))r.refMods[changed.id]={w:hash(b.writesBytes(changed)),...(changed.append?{p:hash(b.buildPayload(changed.append,args[2],stock))}:{})};return r;};});})();
'''
def main():
 p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');a=p.parse_args();old=json.loads((ROOT/'docs/flasher-quick-save-test/quick-save-data.js').read_text().split('=',1)[1].strip().rstrip(';'));w=json.loads((ROOT/'firmware/wizard-catalogue.json').read_text())['variants']['0']['wizard'];origin=(int(w['append']['dest'],16)+w['append']['size']+15)&~15
 cross=next(c for c in ('m68k-linux-gnu-','m68k-elf-') if shutil.which(c+'as'))
 with tempfile.TemporaryDirectory() as tmp:
  p=pathlib.Path(tmp);subprocess.run([cross+'as','-march=cfv4e','-o',str(p/'x.o'),str(ROOT/'tools/machines/quick_save/latch_exit.s')],check=True);(p/'x.ld').write_text(f"SET_HELD = {old['symbols']['set_held']}; SECTIONS {{ .text {origin:#x} : {{ *(.text) }} }}");subprocess.run([cross+'ld','-T',str(p/'x.ld'),'-o',str(p/'x.elf'),str(p/'x.o')],check=True);subprocess.run([cross+'objcopy','-O','binary',str(p/'x.elf'),str(p/'x.bin')],check=True);code=(p/'x.bin').read_bytes()
 data=dict(at=old['at'],size=old['size'],old=old['hex'],hex=code.hex());target=ROOT/'docs/flasher-quick-save-test';files={'quick-save-latch.js':JS,'quick-save-latch-data.js':'window.MCQuickSaveLatch='+json.dumps(data,separators=(',',':'))+';\n'}
 files['diagnostic-release.js']='window.MC_RELEASES='+json.dumps([dict(version='Quick-save-test.3',date='2026-10-17',changes=[dict(en='Quick save closes the underlying mute view through its native close path before opening the save menu. Diagnostics retained; main unchanged. Keep Control All Beat Repeat selected in this test.',fr='La sauvegarde rapide ferme la vue mute via son chemin natif avant ouverture du menu sauvegarde. Diagnostics conserves ; principal inchange. Garder Control All Beat Repeat selectionne dans ce test.')])],ensure_ascii=False)+';\n'
 for name,text in files.items():
  if a.check:assert (target/name).read_text(encoding='utf-8').replace('\r\n','\n')==text,name
  else:(target/name).write_text(text,encoding='utf-8')
 s=(target/'index.html').read_text(encoding='utf-8');s=re.sub(r'(?<=\?v=)[\w.-]+',STAMP,s);s=re.sub(r"window.MC_BUILD='[^']+'",f"window.MC_BUILD='{STAMP}'",s)
 if 'src="quick-save-latch.js?' not in s:s=s.replace('</body>',f'<script src="quick-save-latch-data.js?v={STAMP}"></script><script src="quick-save-latch.js?v={STAMP}"></script></body>')
 s=re.sub(r'(<main class="wrap fl">)<p>.*?</p>',lambda m:m.group(1)+'<p><strong data-l="en">Quick-save test 3:</strong><strong data-l="fr">Test sauvegarde rapide 3 :</strong> <span data-l="en">Hold FUNCTION + SETTINGS. After closing the save menu and releasing FUNCTION, its light and momentary mute mode should clear. Other SETTINGS shortcuts remain unchanged. Keep Control All Beat Repeat selected for this diagnostic test. Diagnostics retained; main unchanged.</span><span data-l="fr">Maintenir FUNCTION + SETTINGS. Apres fermeture du menu sauvegarde et relachement de FUNCTION, sa LED et le mute momentane doivent se terminer. Autres raccourcis SETTINGS conserves. Garder Control All Beat Repeat selectionne pour ce test diagnostic. Diagnostics conserves ; principal inchange.</span></p>',s,count=1,flags=re.S)
 if not a.check:(target/'index.html').write_text(s,encoding='utf-8')
 else:assert (target/'index.html').read_text(encoding='utf-8')==s
 print('PASS quick save latch',len(code),'octets, test seulement')
if __name__=='__main__':main()

